#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXV 8

static int adj[MAXV][MAXV];   // adjacency matrix
static int color[MAXV];      // 0 = unvisited, 1 = visiting, 2 = visited
static int found_cycle;      // non‑zero if a cycle is detected

static void dfs(int v) {
    int u;
    if (found_cycle) return;          // early exit if cycle already found
    color[v] = 1;                     // mark as visiting
    for (u = 0; u < MAXV; ++u) {
        if (!adj[v][u]) continue;    // no edge v->u
        if (color[u] == 0) {         // tree edge
            dfs(u);
            if (found_cycle) return;
        } else if (color[u] == 1) { // back edge -> cycle
            found_cycle = 1;
            return;
        }
        // color[u] == 2 (already finished) does not create a cycle
    }
    color[v] = 2;                     // finished
}

int main(int argc, char *argv[]) {
    int i, edge_cnt;
    long src, dst;

    // Input validation: need even number of numeric arguments and each vertex in [0,7]
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }
    if ((argc - 1) % 2 != 0) {
        puts("INVALID_INPUT");
        return 0;
    }
    edge_cnt = (argc - 1) / 2;

    memset(adj, 0, sizeof(adj));
    for (i = 0; i < edge_cnt; ++i) {
        src = strtol(argv[1 + 2 * i], NULL, 10);
        dst = strtol(argv[2 + 2 * i], NULL, 10);
        if (src < 0 || src >= MAXV || dst < 0 || dst >= MAXV) {
            puts("INVALID_INPUT");
            return 0;
        }
        adj[(int)src][(int)dst] = 1;
    }

    memset(color, 0, sizeof(color));
    found_cycle = 0;
    for (i = 0; i < MAXV; ++i) {
        if (color[i] == 0) dfs(i);
        if (found_cycle) break;
    }

    puts(found_cycle ? "CYCLE" : "ACYCLIC");
    return 0;
}
